export const COMPONENTS = {"button":{"status":"stable","factory":"uiButton","purpose":"Named text action with stable geometry across emphasis and state.","variants":["neutral","primary","danger","quiet"],"sizes":["compact","default"],"states":["default","hover","focus","pressed","disabled","busy"],"example":"uiButton({label:'Save', emphasis:'primary', onClick:save})"},"iconButton":{"status":"stable","factory":"iconButton","purpose":"Familiar symbol with required accessible name and shared tooltip.","sizes":["compact","default"],"states":["default","hover","focus","pressed","disabled"],"example":"iconButton('settings', 'Settings', openSettings)"},"field":{"status":"stable","factory":"uiField","purpose":"Native field with associated label, hint and validation error.","states":["default","focus","invalid","disabled"],"example":"uiField(input, {label:'Collection title'}).setError('Enter a title')"},"toggle":{"status":"stable","factory":"uiToggle","purpose":"Native checkbox in a labelled settings row.","states":["unchecked","checked","focus","disabled"],"example":"uiToggle({label:'Show source details', checked:false, onChange:save})"},"dialog":{"status":"stable","factory":"uiDialog","purpose":"Named native modal with Escape, contained focus and focus return.","states":["closed","open"],"example":"uiDialog(panel, {trigger, closeButton})","variants":["modal","drawer"]},"menu":{"status":"stable","factory":"uiMenu","purpose":"Native popover with arrows, Home/End, first-letter navigation and dismissal.","states":["closed","open"],"example":"uiMenu(menu, trigger)"},"tooltip":{"status":"stable","factory":"data-tooltip","purpose":"One delegated tooltip: 150ms hover, immediate keyboard, dismissible and hoverable.","states":["hidden","visible"],"example":"iconButton('plus', 'Add source', addSource)"},"toolbar":{"status":"stable","factory":"uiToolbar","purpose":"Wrapping named action group with ordinary Tab navigation.","example":"uiToolbar({label:'Collection actions'}, save, cancel)"},"settingsRow":{"status":"stable","factory":"uiSettingsRow","purpose":"Compact label/control pair, with hints and errors below.","example":"uiSettingsRow(select, {label:'Open stories'})"},"metadata":{"status":"stable","factory":"uiMetadata","purpose":"Wrapping secondary information and compact named actions.","example":"uiMetadata({className:'item-meta'}, age, saveButton)"},"card":{"status":"stable","factory":"uiCard","purpose":"Semantic article with heading, description, metadata and independent actions.","example":"uiCard({title:'Reading list', description:'Kept reading', actions:[open]})"},"feedback":{"status":"stable","factory":"uiFeedback","purpose":"Consistent empty, loading, error, information and success states with optional recovery action.","variants":["empty","loading","error","info","success"],"example":"uiFeedback({kind:'error', message:'Could not load collections', action:retry})"},"tabs":{"status":"stable","factory":"uiTabs","purpose":"Local panels with manual activation, roving focus and optional wide overview.","states":["selected","unselected","disabled","focus","overview"],"example":"uiTabs({label:'Sources', items:[{label:'One',panel:first},{label:'Two',panel:second}]})"},"disclosure":{"status":"stable","factory":"uiDisclosure","purpose":"Native details with a consistent summary. A shared name creates an exclusive accordion.","variants":["independent","exclusive"],"states":["closed","open","focus"],"example":"uiDisclosure({label:'Filters'}, fields)"},"badge":{"status":"stable","factory":"uiBadge","purpose":"Passive status or tag pill; no action, focus target or hover tooltip.","variants":["neutral","accent","success","warning","error"],"example":"uiBadge({label:'New',tone:'accent'})"},"chip":{"status":"stable","factory":"uiChip","purpose":"Selectable pill with a stable label, pressed state and reserved checkmark.","states":["unselected","selected","disabled","focus"],"example":"uiChip({label:'Select',onChange:choose}).element"},"tray":{"status":"stable","factory":"uiTray","purpose":"Contextual action group in document flow. No modal semantics or focus trap.","states":["hidden","visible"],"example":"uiTray({label:'Selected material'}, count, compare, clear)"},"navigationLink":{"status":"stable","factory":"uiNavLink","purpose":"Underlineless destination row in application navigation, with current-page indication.","states":["default","hover","focus","current"],"example":"uiNavLink({label:'Installation',href:page.url,onClick:open})"},"pager":{"status":"stable","factory":"uiPager","purpose":"Previous/next document actions with visible destination titles, wrapping at narrow widths.","states":["both","first","last"],"example":"uiPager({next:{label:'Installation',onClick:nextPage}})"},"document":{"status":"stable","factory":".ui-document","purpose":"Comfortable prose, underlined content links, headings, code, tables, quotes and media; separate from compact chrome.","variants":["article","documentation"],"example":"el('div',{class:'body ui-document'},blockNodes(page.blocks))"},"form":{"status":"stable","factory":"uiForm","purpose":"Native validation, associated field errors, guarded async submission and persistent inline server errors.","example":"uiForm(form,{submit:save,onSubmit:persist})"},"choiceGroup":{"status":"stable","factory":"uiChoiceGroup","purpose":"Named segmented native radios with native arrow keys, stable targets and visible selection.","example":"uiChoiceGroup({label:'Audience',value:'everyone',choices:[{value:'everyone',label:'Public'}]})"},"popover":{"status":"stable","factory":"uiPopover","purpose":"Rich nonmodal popover with ordinary Tab, native form keys, Escape, outside dismissal and viewport positioning.","example":"uiPopover(panel,trigger)"},"toast":{"status":"stable","factory":"uiToasts","purpose":"Three visible dismissible notices and a deduplicated FIFO queue; persistent errors and paused confirmation timers.","example":"uiToasts(region).show('Saved','success')","variants":["info","success","error"]},"progress":{"status":"stable","factory":"uiProgress","purpose":"Named native progress; real values or indeterminate work, with readable status.","example":"uiProgress({label:'Reading progress',value:2,max:10,message:'2 of 10 stories'})","variants":["determinate","indeterminate"]},"skeleton":{"status":"stable","factory":"uiSkeleton","purpose":"Decorative static loading placeholder paired with readable loading status.","example":"uiSkeleton({lines:3})"}} as const;
